// Tool names are used directly - no prefix needed for gateway
const selectedTool = $input.first().json['Tool Name'];
const argsJson = $input.first().json['Query/Arguments (JSON)'] || '{}';

let args = {};
try {
  args = JSON.parse(argsJson);
} catch (e) {
  args = {};
}

const gatewayUrl = 'http://172.17.0.1:18888/mcp';
const headers = {
  'Authorization': 'Bearer eib-mcp-gateway-token-2025',
  'Content-Type': 'application/json',
  'Accept': 'application/json, text/event-stream'
};

// Step 1: Initialize session
const initPayload = {
  jsonrpc: '2.0',
  id: 1,
  method: 'initialize',
  params: {
    protocolVersion: '2024-11-05',
    capabilities: {},
    clientInfo: { name: 'n8n-mcp-client', version: '1.0.0' }
  }
};

const initResponse = await this.helpers.httpRequest({
  method: 'POST',
  url: gatewayUrl,
  headers: headers,
  body: initPayload,
  returnFullResponse: true,
  json: true
});

// Get session ID from response header
const sessionId = initResponse.headers['mcp-session-id'];

if (!sessionId) {
  return { json: { success: false, toolCalled: selectedTool, output: 'Failed to get session ID. Headers: ' + JSON.stringify(initResponse.headers) } };
}

// Step 2: Call the tool with session ID (use tool name directly, no prefix)
const toolPayload = {
  jsonrpc: '2.0',
  id: 2,
  method: 'tools/call',
  params: {
    name: selectedTool,
    arguments: args
  }
};

const toolResponse = await this.helpers.httpRequest({
  method: 'POST',
  url: gatewayUrl,
  headers: {
    ...headers,
    'Mcp-Session-Id': sessionId
  },
  body: toolPayload,
  returnFullResponse: true,
  json: false
});

const toolBody = typeof toolResponse.body === 'string' ? toolResponse.body : JSON.stringify(toolResponse.body);

// Parse SSE response
let formattedOutput = '';
const dataMatches = toolBody.match(/data: ({[^\n]+})/g);
if (dataMatches) {
  for (const dm of dataMatches) {
    try {
      const jsonStr = dm.replace('data: ', '');
      const parsed = JSON.parse(jsonStr);
      if (parsed.result && parsed.result.content) {
        parsed.result.content.forEach(item => {
          if (item.type === 'text') {
            formattedOutput += item.text;
          }
        });
      } else if (parsed.error) {
        formattedOutput = 'Error: ' + (parsed.error.message || JSON.stringify(parsed.error));
      }
    } catch (e) {
      // Skip parse errors
    }
  }
}

if (!formattedOutput) {
  formattedOutput = toolBody;
}

return { json: { success: !formattedOutput.startsWith('Error'), toolCalled: selectedTool, sessionId, output: formattedOutput } };
